DROP SCHEMA IF EXISTS c_record_ref CASCADE; CREATE SCHEMA c_record_ref; SET search_path=c_record_ref,public;
CREATE TYPE leaf AS (n smallint, label varchar(2));
CREATE TYPE pair AS (nested leaf, optional integer, numbers integer[], amount numeric(5,2));
CREATE TYPE fields AS (a integer, b text COLLATE "C", c numeric(7,2));
